# frozen_string_literal: true

require 'zlib'

module Meshtastic
  # Bounded decoding of the official TAKPacket-SDK wire envelope.
  module PayloadCompression
    MAX_DECODED = 4096
    class Unavailable < StandardError; end

    public_class_method def self.decode_v2(opts = {})
      bytes = opts.fetch(:payload).to_s.b
      raise ArgumentError, 'empty ATAK V2 payload' if bytes.empty?
      raise ArgumentError, 'ATAK V2 input exceeds 4097 bytes' if bytes.bytesize > MAX_DECODED + 1

      flags = bytes.getbyte(0)
      body = bytes.byteslice(1..)
      return body if flags == 0xff

      id = flags & 0x3f
      raise ArgumentError, "unknown ATAK V2 dictionary id #{id}" unless id < 2

      dictionary = Zlib::Inflate.inflate(DICTIONARIES.fetch(id).unpack1('m0'))
      zstd_decode(payload: "\x28\xb5\x2f\xfd".b + body, dictionary: dictionary)
    end

    public_class_method def self.authors
      'Meshtastic contributors; dictionaries from Meshtastic TAKPacket-SDK (GPL-3.0)'
    end

    public_class_method def self.help
      puts "USAGE:
        # Decode bounded ATAK V2 protobuf bytes.
        #{self}.decode_v2(payload: 'required - flags-prefixed ATAK V2 wire bytes')
        # Report codec resource authors.
        #{self}.authors
      "
    end

    private_class_method def self.native
      require 'fiddle'
      library = nil
      %w[libzstd.so.1 libzstd.so libzstd.1.dylib libzstd.dylib zstd.dll].each do |name|
        library = Fiddle.dlopen(name)
        break
      rescue Fiddle::DLError
        next
      end
      raise Unavailable, 'ATAK V2 requires libzstd (install the Zstandard shared library)' unless library

      pointer = Fiddle::TYPE_VOIDP
      size = Fiddle::TYPE_SIZE_T
      signatures = {
        create: ['ZSTD_createDCtx', [], pointer],
        free: ['ZSTD_freeDCtx', [pointer], size],
        frame_size: ['ZSTD_findFrameCompressedSize', [pointer, size], size],
        decode: ['ZSTD_decompress_usingDict', [pointer, pointer, size, pointer, size, pointer, size], size],
        error: ['ZSTD_isError', [size], Fiddle::TYPE_INT]
      }
      signatures.transform_values { |name, args, result| Fiddle::Function.new(library[name], args, result) }.merge(library: library)
    rescue LoadError, Fiddle::DLError => e
      raise Unavailable, "ATAK V2 requires Ruby fiddle and libzstd: #{e.message}"
    end

    private_class_method def self.zstd_decode(opts = {})
      functions = native
      input = opts.fetch(:payload)
      dict = opts.fetch(:dictionary)
      frame_size = functions[:frame_size].call(input, input.bytesize)
      raise ArgumentError, 'malformed ATAK V2 zstd frame (truncated or trailing bytes)' if functions[:error].call(frame_size) != 0 || frame_size != input.bytesize

      context = functions[:create].call
      raise Unavailable, 'cannot allocate zstd decoder context' if context.null?

      begin
        output = "\0".b * MAX_DECODED
        size = functions[:decode].call(context, output, output.bytesize, input, input.bytesize, dict, dict.bytesize)
        raise ArgumentError, 'invalid ATAK V2 zstd data or decoded output exceeds 4096 bytes' if functions[:error].call(size) != 0

        output.byteslice(0, size)
      ensure
        functions[:free].call(context)
      end
    end
  end
end

# Official dictionaries: TAKPacket-SDK 7ace3c786c1559938cd4d1d3870e3bdd66ecb2e9, GPL-3.0.
# Deflate/base64 embedding keeps resources in the gem manifest without runtime downloads.
Meshtastic::PayloadCompression::DICTIONARIES = ["", ""].freeze
